SELECT p.pid,t.tid,s.ts,s.dur,s.state,s.io_wait,s.blocked_function FROM thread_state s JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid IN (6294,6859,7540,8041,8676,9240,9745,10234,10762,11178) AND (t.tid IN (6316,6316,6883,6883,7561,7561,8063,8063,8696,8696,9261,9261,9769,9769,10259,10259,10787,10787,11202,11202) OR t.tid=p.pid) AND s.ts < 370058225200 AND s.ts+s.dur > 190038550000 ORDER BY p.pid,t.tid,s.ts;
